这是个非常关键的问题！DeepSeek导出的JSON数据量一大，原生`JSON.parse` + `filter` + `includes`确实会慢到崩溃。IndexedDB本身不支持全文索引，但有几种成熟的方案。

---

## 方案对比

| 方案 | 全文搜索 | 索引效率 | 包大小 | 适用场景 |
|------|----------|----------|--------|----------|
| **Dexie + 关键词分詞** | ⭐⭐⭐ | 快 | ~30KB | 中文搜索，数据量<10万条 |
| **Lunr.js** | ⭐⭐⭐⭐ | 中 | ~20KB | 通用全文搜索，需维护索引 |
| **FlexSearch** | ⭐⭐⭐⭐⭐ | 极快 | ~10KB | 高性能全文搜索，推荐！ |
| **MiniSearch** | ⭐⭐⭐⭐ | 快 | ~15KB | 轻量，简单易用 |
| **SQLite (wa-sqlite)** | ⭐⭐⭐⭐⭐ | 极快 | ~1MB | 需要复杂查询，重型方案 |

---

## 推荐方案：FlexSearch + Dexie 组合

```
┌─────────────────────────────────────────────────────────┐
│  用户导入 JSON                                          │
│      ↓                                                 │
│  解析 + 分词 (FlexSearch)                              │
│      ↓                                                 │
│  ┌──────────────┐    ┌──────────────┐                 │
│  │  IndexedDB    │    │  FlexSearch  │                 │
│  │  (Dexie)      │    │  (内存索引)   │                 │
│  │  存储完整数据  │    │  存储倒排索引 │                 │
│  └──────────────┘    └──────────────┘                 │
│         ↑                    ↑                         │
│         └──── 查询时 ────────┘                         │
│        先搜索引拿ID，再查DB拿完整数据                     │
└─────────────────────────────────────────────────────────┘
```

---

## 完整实现代码

### 1. 安装依赖

```bash
npm install dexie flexsearch
```

### 2. 数据库设计

```typescript
// db.ts
import Dexie, { Table } from 'dexie';

// 对话数据结构（扁平化）
export interface MessageRecord {
  id: string;           // 消息ID
  conversationId: string; // 所属对话ID
  conversationTitle: string;
  role: 'user' | 'assistant';
  content: string;      // 消息正文（需要被搜索）
  timestamp: Date;
  model?: string;
  // 额外搜索优化字段
  contentLength: number;
  wordCount: number;
}

export interface ConversationMeta {
  id: string;
  title: string;
  insertedAt: Date;
  updatedAt: Date;
  messageCount: number;
}

class DeepSeekDB extends Dexie {
  messages!: Table<MessageRecord, string>;
  conversations!: Table<ConversationMeta, string>;

  constructor() {
    super('DeepSeekDB');
    this.version(1).stores({
      // 复合索引：按对话+时间排序，按角色过滤
      messages: 'id, conversationId, role, timestamp, contentLength',
      conversations: 'id, title, insertedAt, updatedAt, messageCount'
    });
  }
}

export const db = new DeepSeekDB();
```

### 3. FlexSearch 索引封装

```typescript
// search-index.ts
import FlexSearch from 'flexsearch';

// 创建中文分词器（简单版）
function tokenize(text: string): string[] {
  // 中文按字切分 + 英文按词切分
  const chinese = text.match(/[\u4e00-\u9fa5]/g) || [];
  const english = text.toLowerCase().match(/[a-zA-Z]{2,}/g) || [];
  return [...chinese, ...english];
}

export class SearchEngine {
  private index: FlexSearch.Index;
  private docMap: Map<string, MessageRecord> = new Map();

  constructor() {
    this.index = new FlexSearch.Index({
      tokenize: (str) => tokenize(str),
      resolution: 9,        // 精度：9=最高
      optimize: true,
      cache: 100,           // 缓存最近100个查询
      language: 'en'        // 使用英文分词器，配合自定义tokenize
    });
  }

  // 批量添加消息
  async addBatch(messages: MessageRecord[]) {
    const batch = messages.map(msg => ({
      id: msg.id,
      content: msg.content
    }));

    // 分批添加，防止阻塞UI
    const chunkSize = 500;
    for (let i = 0; i < batch.length; i += chunkSize) {
      const chunk = batch.slice(i, i + chunkSize);
      chunk.forEach(({ id, content }) => {
        this.index.add(id, content);
        // 同时存储完整消息引用
        const msg = messages.find(m => m.id === id);
        if (msg) this.docMap.set(id, msg);
      });
      // 让出主线程
      await new Promise(resolve => setTimeout(resolve, 0));
    }
  }

  // 搜索
  search(query: string, limit: number = 50): MessageRecord[] {
    if (!query.trim()) return [];

    const startTime = performance.now();

    // 先通过FlexSearch获取匹配的ID列表（按相关性排序）
    const results = this.index.search(query, {
      limit: limit,
      suggest: true,       // 支持拼写建议
      enrich: false        // 只返回ID，提升性能
    });

    // 从docMap获取完整数据
    const messages = results
      .map(id => this.docMap.get(id as string))
      .filter((msg): msg is MessageRecord => msg !== undefined);

    console.log(`搜索 "${query}" 耗时 ${performance.now() - startTime}ms，找到 ${messages.length} 条`);
    return messages;
  }

  // 清空索引
  clear() {
    this.index = new FlexSearch.Index({
      tokenize: (str) => tokenize(str),
      resolution: 9,
      optimize: true
    });
    this.docMap.clear();
  }

  // 获取索引统计
  stats() {
    return {
      indexed: this.docMap.size,
      memory: '~' + (this.docMap.size * 0.5).toFixed(1) + 'MB'
    };
  }
}

export const searchEngine = new SearchEngine();
```

### 4. 数据导入流程（优化版）

```typescript
// import-service.ts
import { db, MessageRecord, ConversationMeta } from './db';
import { searchEngine } from './search-index';

export class ImportService {
  // 分批导入，显示进度
  async importConversations(jsonData: any[], onProgress?: (percent: number) => void) {
    const total = jsonData.length;
    let processed = 0;
    const allMessages: MessageRecord[] = [];

    for (const conv of jsonData) {
      // 保存对话元数据
      const meta: ConversationMeta = {
        id: conv.id,
        title: conv.title || '未命名对话',
        insertedAt: new Date(conv.inserted_at),
        updatedAt: new Date(conv.updated_at),
        messageCount: 0
      };

      // 解析消息树
      const messages = this.parseMessageTree(conv);
      meta.messageCount = messages.length;

      // 批量保存消息
      const messageRecords = messages.map(msg => ({
        ...msg,
        conversationId: conv.id,
        conversationTitle: meta.title,
        contentLength: msg.content.length,
        wordCount: this.countWords(msg.content)
      }));

      allMessages.push(...messageRecords);

      // 分批写入IndexedDB（防止事务过大）
      if (allMessages.length >= 1000) {
        await this.flushToDB(allMessages, meta);
        allMessages.length = 0;
      }

      processed++;
      if (onProgress) {
        onProgress(Math.round((processed / total) * 100));
      }
    }

    // 写入剩余数据
    if (allMessages.length > 0) {
      await this.flushToDB(allMessages);
    }

    // 构建全文索引
    await this.buildSearchIndex();
  }

  private async flushToDB(messages: MessageRecord[], meta?: ConversationMeta) {
    await db.transaction('rw', db.messages, db.conversations, async () => {
      if (meta) {
        await db.conversations.put(meta);
      }
      await db.messages.bulkPut(messages);
    });
  }

  private parseMessageTree(conv: any): Omit<MessageRecord, 'conversationId' | 'conversationTitle' | 'contentLength' | 'wordCount'>[] {
    const messages: any[] = [];
    const mapping = conv.mapping;

    let currentId = 'root';
    while (true) {
      const node = mapping[currentId];
      if (!node || node.children.length === 0) break;

      const childId = node.children[0];
      const childNode = mapping[childId];

      if (childNode.message) {
        const frag = childNode.message.fragments[0];
        if (frag) {
          messages.push({
            id: childId,
            role: frag.type === 'REQUEST' ? 'user' : 'assistant',
            content: frag.content,
            timestamp: new Date(childNode.message.inserted_at),
            model: childNode.message.model
          });
        }
      }
      currentId = childId;
    }

    return messages;
  }

  private countWords(text: string): number {
    // 中英文混合字数统计
    const chinese = (text.match(/[\u4e00-\u9fa5]/g) || []).length;
    const english = (text.match(/[a-zA-Z]+/g) || []).length;
    return chinese + english;
  }

  private async buildSearchIndex() {
    const allMessages = await db.messages.toArray();
    await searchEngine.addBatch(allMessages);
  }
}
```

### 5. 搜索服务（整合）

```typescript
// search-service.ts
import { db, MessageRecord } from './db';
import { searchEngine } from './search-index';

export interface SearchResult {
  messages: MessageRecord[];
  total: number;
  time: number;
  highlight?: string; // 高亮片段
}

export class SearchService {
  // 混合搜索：先搜全文索引，再按对话/时间过滤
  async search(
    query: string,
    filters?: {
      conversationId?: string;
      role?: 'user' | 'assistant';
      dateFrom?: Date;
      dateTo?: Date;
    },
    limit: number = 50
  ): Promise<SearchResult> {
    const start = performance.now();

    // 1. 全文搜索获取消息ID列表
    let messageIds = searchEngine.search(query, limit * 2); // 多取一些用于过滤

    // 2. 从IndexedDB批量获取完整数据
    let messages: MessageRecord[] = [];
    if (messageIds.length > 0) {
      const ids = messageIds.map(m => m.id);
      messages = await db.messages.bulkGet(ids);
      // 过滤掉null值
      messages = messages.filter((m): m is MessageRecord => m !== undefined);
    }

    // 3. 应用过滤器
    if (filters) {
      messages = messages.filter(m => {
        if (filters.conversationId && m.conversationId !== filters.conversationId) return false;
        if (filters.role && m.role !== filters.role) return false;
        if (filters.dateFrom && m.timestamp < filters.dateFrom) return false;
        if (filters.dateTo && m.timestamp > filters.dateTo) return false;
        return true;
      });
    }

    // 4. 按相关性和时间排序（FlexSearch默认按相关性排序）
    // 但我们可以二次排序
    messages.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

    const time = performance.now() - start;

    return {
      messages: messages.slice(0, limit),
      total: messages.length,
      time
    };
  }

  // 搜索建议（自动补全）
  async suggestions(prefix: string): Promise<string[]> {
    if (prefix.length < 2) return [];

    // 从索引中获取建议
    const results = searchEngine.search(prefix, 20);
    // 提取关键词
    const keywords = new Set<string>();
    results.forEach(msg => {
      const words = msg.content.split(/[\s,，。、；;：:！!？?]/);
      words.forEach(word => {
        if (word.length > 1 && word.includes(prefix)) {
          keywords.add(word);
        }
      });
    });

    return Array.from(keywords).slice(0, 10);
  }
}
```

---

## 性能优化关键点

### 1. 增量索引（避免重复构建）

```typescript
// 检查哪些消息已索引，只添加新增的
async incrementalIndex() {
  const existingIds = await db.messages
    .where('id')
    .anyOf([...searchEngine.docMap.keys()])
    .primaryKeys();

  const newMessages = await db.messages
    .where('id')
    .noneOf(existingIds)
    .toArray();

  await searchEngine.addBatch(newMessages);
}
```

### 2. 搜索去抖动

```typescript
// 用户输入时防抖
import { debounce } from 'lodash-es';

const debouncedSearch = debounce(async (query: string) => {
  const results = await searchService.search(query);
  setResults(results);
}, 300);
```

### 3. 索引持久化（避免每次加载重建）

```typescript
// 将FlexSearch索引导出为JSON并存储到IndexedDB
async persistIndex() {
  const indexData = searchEngine.index.export();
  await db.indexState.put({
    id: 'main',
    data: indexData,
    updatedAt: new Date()
  });
}

async loadIndex() {
  const saved = await db.indexState.get('main');
  if (saved) {
    searchEngine.index.import(saved.data);
    // 重建docMap
    const messages = await db.messages.toArray();
    messages.forEach(msg => searchEngine.docMap.set(msg.id, msg));
  }
}
