// db.ts
import Dexie, { Table } from 'dexie';

export interface ConversationRecord {
  id: string;           // 对话ID
  title: string;
  inserted_at: string;
  updated_at: string;
  messages: Message[];  // 解析后的消息列表
  messageCount: number;
  lastMessageAt: string;
}

export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
  model?: string;
}

// 搜索索引表 - 存储每个消息的索引数据
export interface SearchIndexRecord {
  id: string;           // 格式: `${conversationId}_${messageId}`
  conversationId: string;
  messageId: string;
  content: string;      // 索引内容
  role: string;
  timestamp: string;
}

class DeepSeekDB extends Dexie {
  conversations!: Table<ConversationRecord, string>;
  searchIndex!: Table<SearchIndexRecord, string>;

  constructor() {
    super('DeepSeekDB');

    this.version(1).stores({
      conversations: 'id, title, inserted_at, updated_at, messageCount, lastMessageAt',
      searchIndex: 'id, conversationId, role, timestamp'
    });
  }
}

export const db = new DeepSeekDB();
