### 3. FlexSearch 索引管理

```typescript
// searchEngine.ts
import FlexSearch from 'flexsearch';
import { db, SearchIndexRecord } from './db';

// 中文分词器（简化版，可替换为更专业的分词）
function tokenize(text: string): string[] {
  // 简单分词：按空格、标点分割，保留中文字符
  return text
    .replace(/[，。！？；：""''（）\n\r\t]/g, ' ')
    .split(/\s+/)
    .filter(word => word.length > 0);
}

export class SearchEngine {
  private index: FlexSearch.Index;
  private isReady: boolean = false;
  private indexSize: number = 0;

  constructor() {
    this.index = new FlexSearch.Index({
      tokenize: tokenize,
      charset: 'latin:simple',  // 支持中文
      cache: true,
      resolution: 9,            // 索引精度，9最高
      minlength: 1,
      async: true,              // 异步索引
      worker: true              // 启用Web Worker
    });
  }

  /**
   * 初始化：从IndexedDB加载数据建立索引
   */
  async initialize(): Promise<void> {
    if (this.isReady) return;

    const records = await db.searchIndex.toArray();

    // 批量添加到FlexSearch
    const tasks = records.map(record => 
      this.index.addAsync(record.id, record.content)
    );

    await Promise.all(tasks);
    this.indexSize = records.length;
    this.isReady = true;

    console.log(`✅ 索引已建立: ${this.indexSize} 条消息`);
  }

  /**
   * 添加单条消息到索引
   */
  async indexMessage(record: SearchIndexRecord): Promise<void> {
    await this.index.addAsync(record.id, record.content);
    this.indexSize++;
  }

  /**
   * 批量添加
   */
  async indexMessages(records: SearchIndexRecord[]): Promise<void> {
    const tasks = records.map(r => this.index.addAsync(r.id, r.content));
    await Promise.all(tasks);
    this.indexSize += records.length;
  }

  /**
   * 删除消息索引
   */
  async removeMessage(id: string): Promise<void> {
    await this.index.removeAsync(id);
    this.indexSize--;
  }

  /**
   * 搜索
   * @returns 匹配的 SearchIndexRecord 数组
   */
  async search(query: string, limit: number = 50): Promise<SearchIndexRecord[]> {
    if (!query.trim() || !this.isReady) {
      return [];
    }

    // FlexSearch 执行搜索，返回 ID 列表
    const results = await this.index.searchAsync(query, {
      limit: limit,
      suggest: true,        // 启用拼写建议
      boost: (field, term, index) => {
        // 加权：标题匹配加权更高
        return field === 'title' ? 2 : 1;
      }
    });

    if (results.length === 0) return [];

    // 从 IndexedDB 批量获取完整数据
    const records = await db.searchIndex
      .where('id')
      .anyOf(results as string[])
      .toArray();

    // 按搜索结果顺序排序
    const orderMap = new Map(results.map((id, idx) => [id, idx]));
    records.sort((a, b) => (orderMap.get(a.id) || 0) - (orderMap.get(b.id) || 0));

    return records;
  }

  /**
   * 搜索并返回对话级别的结果（去重）
   */
  async searchConversations(query: string, limit: number = 50): Promise<{
    conversationId: string;
    matchedMessages: SearchIndexRecord[];
  }[]> {
    const results = await this.search(query, limit * 3); // 多取一些用于去重

    // 按 conversationId 分组
    const grouped = new Map<string, SearchIndexRecord[]>();
    for (const record of results) {
      if (!grouped.has(record.conversationId)) {
        grouped.set(record.conversationId, []);
      }
      grouped.get(record.conversationId)!.push(record);
    }

    // 转换为数组，按匹配数量排序
    return Array.from(grouped.entries())
      .map(([conversationId, matchedMessages]) => ({
        conversationId,
        matchedMessages
      }))
      .sort((a, b) => b.matchedMessages.length - a.matchedMessages.length)
      .slice(0, limit);
  }

  /**
   * 获取索引统计
   */
  getStats() {
    return {
      isReady: this.isReady,
      totalIndexed: this.indexSize
    };
  }

  /**
   * 重建索引
   */
  async rebuildIndex(): Promise<void> {
    this.index = new FlexSearch.Index({
      tokenize: tokenize,
      charset: 'latin:simple',
      cache: true,
      resolution: 9,
      minlength: 1,
      async: true,
      worker: true
    });
    this.isReady = false;
    this.indexSize = 0;
    await this.initialize();
  }
}

export const searchEngine = new SearchEngine();
```

### 4. 数据导入与索引同步

```typescript
// dataManager.ts
import { db, ConversationRecord, SearchIndexRecord } from './db';
import { searchEngine } from './searchEngine';

export class DataManager {
  /**
   * 导入对话数据
   */
  async importConversations(rawData: any[]): Promise<{
    imported: number;
    indexed: number;
  }> {
    let importedCount = 0;
    let indexedCount = 0;

    for (const conversation of rawData) {
      // 1. 解析对话为消息列表
      const messages = this.parseMapping(conversation.mapping);

      // 2. 存储到 IndexedDB
      const record: ConversationRecord = {
        id: conversation.id,
        title: conversation.title || '未命名对话',
        inserted_at: conversation.inserted_at,
        updated_at: conversation.updated_at,
        messages: messages,
        messageCount: messages.length,
        lastMessageAt: messages[messages.length - 1]?.timestamp || conversation.updated_at
      };

      await db.conversations.put(record);
      importedCount++;

      // 3. 构建搜索索引
      const indexRecords: SearchIndexRecord[] = messages.map(msg => ({
        id: `${conversation.id}_${msg.id}`,
        conversationId: conversation.id,
        messageId: msg.id,
        content: msg.content,
        role: msg.role,
        timestamp: msg.timestamp
      }));

      // 4. 存到 searchIndex 表
      await db.searchIndex.bulkPut(indexRecords);

      // 5. 添加到 FlexSearch 索引
      await searchEngine.indexMessages(indexRecords);
      indexedCount += indexRecords.length;
    }

    return { imported: importedCount, indexed: indexedCount };
  }

  /**
   * 解析 mapping 树为消息列表
   */
  private parseMapping(mapping: any): Message[] {
    const messages: Message[] = [];
    let currentId = 'root';

    while (true) {
      const node = mapping[currentId];
      if (!node || node.children.length === 0) break;

      const childId = node.children[0]; // 取主路径
      const childNode = mapping[childId];

      if (childNode?.message?.fragments) {
        for (const fragment of childNode.message.fragments) {
          if (fragment.type === 'REQUEST' || fragment.type === 'RESPONSE') {
            messages.push({
              id: childId,
              role: fragment.type === 'REQUEST' ? 'user' : 'assistant',
              content: fragment.content,
              timestamp: childNode.message.inserted_at,
              model: childNode.message.model
            });
          }
        }
      }

      currentId = childId;
    }

    return messages;
  }

  /**
   * 删除对话
   */
  async deleteConversation(conversationId: string): Promise<void> {
    // 1. 删除搜索索引
    const indexRecords = await db.searchIndex
      .where('conversationId')
      .equals(conversationId)
      .toArray();

    for (const record of indexRecords) {
      await searchEngine.removeMessage(record.id);
    }

    // 2. 删除数据库记录
    await db.searchIndex.where('conversationId').equals(conversationId).delete();
    await db.conversations.delete(conversationId);
  }

  /**
   * 增量更新对话
   */
  async updateConversation(conversation: ConversationRecord): Promise<void> {
    // 先删除旧数据
    await this.deleteConversation(conversation.id);

    // 重新导入
    const indexRecords: SearchIndexRecord[] = conversation.messages.map(msg => ({
      id: `${conversation.id}_${msg.id}`,
      conversationId: conversation.id,
      messageId: msg.id,
      content: msg.content,
      role: msg.role,
      timestamp: msg.timestamp
    }));

    await db.conversations.put(conversation);
    await db.searchIndex.bulkPut(indexRecords);
    await searchEngine.indexMessages(indexRecords);
  }
}

export const dataManager = new DataManager();
```

### 5. React Hook：搜索功能

```typescript
// useSearch.ts
import { useState, useCallback, useEffect } from 'react';
import { searchEngine } from './searchEngine';
import { db, SearchIndexRecord, ConversationRecord } from './db';

interface SearchResult {
  conversation: ConversationRecord;
  matches: SearchIndexRecord[];
  highlight: string;  // 预览片段
}

export function useSearch() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    // 初始化索引
    searchEngine.initialize().then(() => setIsReady(true));
  }, []);

  const performSearch = useCallback(async (searchQuery: string) => {
    if (!searchQuery.trim() || !isReady) {
      setResults([]);
      return;
    }

    setIsSearching(true);
    setQuery(searchQuery);

    try {
      // 1. 搜索获取匹配的消息
      const matchedMessages = await searchEngine.search(searchQuery, 100);

      if (matchedMessages.length === 0) {
        setResults([]);
        return;
      }

      // 2. 获取对应的对话
      const conversationIds = [...new Set(
        matchedMessages.map(m => m.conversationId)
      )];

      const conversations = await db.conversations
        .where('id')
        .anyOf(conversationIds)
        .toArray();

      // 3. 构建结果
      const resultMap = new Map<string, SearchResult>();
      for (const conv of conversations) {
        resultMap.set(conv.id, {
          conversation: conv,
          matches: [],
          highlight: ''
        });
      }

      for (const match of matchedMessages) {
        const result = resultMap.get(match.conversationId);
        if (result) {
          result.matches.push(match);
          // 生成高亮预览（取第一条匹配的前后文）
          if (!result.highlight) {
            result.highlight = this.generateHighlight(
              match.content, 
              searchQuery
            );
          }
        }
      }

      // 按匹配数量排序
      const sortedResults = Array.from(resultMap.values())
        .sort((a, b) => b.matches.length - a.matches.length);

      setResults(sortedResults);

    } catch (error) {
      console.error('搜索失败:', error);
      setResults([]);
    } finally {
      setIsSearching(false);
    }
  }, [isReady]);

  /**
   * 生成高亮预览
   */
  const generateHighlight = useCallback((text: string, query: string) => {
    const index = text.toLowerCase().indexOf(query.toLowerCase());
    if (index === -1) return text.slice(0, 100) + '...';

    const start = Math.max(0, index - 30);
    const end = Math.min(text.length, index + query.length + 30);
    let preview = text.slice(start, end);

    if (start > 0) preview = '...' + preview;
    if (end < text.length) preview = preview + '...';

    return preview;
  }, []);

  return {
    query,
    results,
    isSearching,
    isReady,
    search: performSearch,
    clearResults: () => setResults([])
  };
}
```

