### 2. 用户状态与权限管理

```typescript
// useSubscription.ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { FeatureKey, FEATURES } from './features';

interface UserState {
  tier: 'free' | 'pro';
  isAuthenticated: boolean;
  userId?: string;
  subscriptionExpiresAt?: string;
  usage: {
    indexedMessages: number;  // 当前索引的消息数
    maxMessages: number;      // 最大限制
  };
}

interface SubscriptionStore extends UserState {
  setTier: (tier: 'free' | 'pro') => void;
  setAuthenticated: (status: boolean) => void;
  incrementUsage: () => void;
  resetUsage: () => void;
  checkFeature: (feature: FeatureKey) => boolean;
  getFeatureLimit: (feature: FeatureKey) => number | null;
}

export const useSubscription = create<SubscriptionStore>()(
  persist(
    (set, get) => ({
      tier: 'free',
      isAuthenticated: false,
      usage: {
        indexedMessages: 0,
        maxMessages: 500
      },

      setTier: (tier) => set({ tier }),

      setAuthenticated: (status) => set({ isAuthenticated: status }),

      incrementUsage: () => {
        const { usage } = get();
        set({
          usage: {
            ...usage,
            indexedMessages: usage.indexedMessages + 1
          }
        });
      },

      resetUsage: () => {
        set({
          usage: {
            indexedMessages: 0,
            maxMessages: 500
          }
        });
      },

      // 检查功能是否可用
      checkFeature: (feature: FeatureKey): boolean => {
        const state = get();
        const definition = FEATURES[feature];

        // 如果是 Pro 功能，检查用户是否为 Pro
        if (definition.tier === 'pro') {
          return state.tier === 'pro';
        }

        // 如果是 Free 功能，检查是否有使用限制
        if (definition.freeLimit !== undefined) {
          if (feature === 'search.limit') {
            return state.usage.indexedMessages < state.usage.maxMessages;
          }
        }

        return true; // 默认可用
      },

      // 获取功能限制值
      getFeatureLimit: (feature: FeatureKey): number | null => {
        const state = get();
        const definition = FEATURES[feature];

        if (definition.tier === 'free' && definition.freeLimit !== undefined) {
          // Pro 用户不受限制
          if (state.tier === 'pro') return null;
          return definition.freeLimit;
        }

        return null;
      }
    }),
    {
      name: 'subscription-storage'  // localStorage 持久化
    }
  )
);
```

