### 4. 搜索功能（带限制）

```typescript
// searchEngine.ts (增强版)
import { useSubscription } from './useSubscription';

export class SearchEngine {
  private index: FlexSearch.Index;
  private isReady: boolean = false;
  private indexedCount: number = 0;

  async addMessage(record: SearchIndexRecord): Promise<void> {
    const { checkFeature, incrementUsage, usage } = useSubscription.getState();

    // 检查是否达到限制
    if (!checkFeature('search.limit')) {
      throw new Error('Search limit exceeded. Upgrade to Pro for unlimited search.');
    }

    await this.index.addAsync(record.id, record.content);
    this.indexedCount++;

    // 更新使用量
    incrementUsage();
  }

  async search(query: string, limit: number = 50): Promise<SearchIndexRecord[]> {
    const { checkFeature } = useSubscription.getState();

    // 检查搜索功能是否可用
    if (!checkFeature('search.limit')) {
      throw new Error('搜索功能已限制，请升级到 Pro 版本');
    }

    // 检查是否支持高级搜索
    const supportsAdvanced = checkFeature('search.advanced');

    let options: any = { limit };

    if (supportsAdvanced) {
      // Pro: 支持模糊搜索、拼音等
      options = {
        ...options,
        suggest: true,
        fuzzy: true,
        boost: { title: 2 }
      };
    }

    const results = await this.index.searchAsync(query, options);
    return results;
  }

  getStats() {
    const { usage, tier } = useSubscription.getState();
    return {
      indexedMessages: usage.indexedMessages,
      maxMessages: usage.maxMessages,
      tier,
      isLimited: usage.indexedMessages >= usage.maxMessages && tier === 'free'
    };
  }
}
