## 后端：用户管理系统

```typescript
// server/models/User.ts
import { PlanTier } from './plans';

export interface User {
  id: string;
  email: string;
  username: string;
  tier: PlanTier;
  createdAt: Date;
  subscription?: {
    plan: PlanTier;
    expiresAt: Date;
    isLifetime: boolean;
    stripeCustomerId?: string;
    stripeSubscriptionId?: string;
  };
  limits: {
    cloudStorageUsed: number; // MB
    devices: string[]; // device IDs
    teamMembers?: string[]; // user IDs
  };
  community: {
    githubUsername?: string;
    discordId?: string;
    prCount: number; // 提过的 PR 数量
    isCoreContributor: boolean;
  };
  betaAccess: string[]; // beta 功能列表
}

// server/services/SubscriptionService.ts
export class SubscriptionService {
  async checkFeature(userId: string, feature: FeatureKey): Promise<boolean> {
    const user = await this.getUser(userId);
    const plan = PLANS[user.tier];
    return plan.features[feature] === true || plan.features[feature] === 'full';
  }

  async getLimit(userId: string, limit: LimitKey): Promise<number | 'unlimited'> {
    const user = await this.getUser(userId);
    const plan = PLANS[user.tier];
    return plan.limits[limit];
  }

  async checkStorage(userId: string): Promise<boolean> {
    const user = await this.getUser(userId);
    const plan = PLANS[user.tier];
    const limit = plan.limits['cloud.storage'];

    if (limit === 'unlimited') return true;
    if (typeof limit !== 'number') return true;

    return user.limits.cloudStorageUsed < limit;
  }

  // Community → Free 自动升级（用户注册即升级）
  async upgradeToFree(userId: string): Promise<void> {
    // 从 Community 升级到 Free（绑定邮箱即升级）
    await this.updateUserTier(userId, 'free');
  }

  // 付费升级
  async upgradeToPaid(userId: string, tier: Exclude<PlanTier, 'community' | 'free'>): Promise<void> {
    // 检查是否已有订阅
    const user = await this.getUser(userId);
    if (user.subscription && !user.subscription.isLifetime) {
      // 升级或降级
      await this.updateSubscription(userId, tier);
    } else {
      // 创建新订阅
      await this.createSubscription(userId, tier);
    }
  }

  // 社区贡献者奖励：为 Ultimate 提供折扣或免费升级
  async rewardContributor(userId: string, prCount: number): Promise<void> {
    if (prCount >= 10) {
      // 10+ PR → 免费 Ultimate 1年
      await this.grantFreeTier(userId, 'ultimate', 365);
    } else if (prCount >= 5) {
      // 5+ PR → 7折优惠码
      await this.grantCoupon(userId, 30);
    }
  }
}
