## 社区 PR 权限管理（Community → Ultimate 的桥梁）

```typescript
// server/services/CommunityService.ts
import { Octokit } from '@octokit/rest';

export class CommunityService {
  private octokit: Octokit;
  private repo = 'deepseek-viewer';
  private owner = 'your-org';

  // 验证 PR 贡献者身份
  async verifyContributor(githubUsername: string): Promise<{
    isContributor: boolean;
    prCount: number;
    mergedPRs: number;
  }> {
    try {
      // 查询该用户在该 repo 的所有 PR
      const { data: prs } = await this.octokit.search.issuesAndPullRequests({
        q: `author:${githubUsername} repo:${this.owner}/${this.repo} type:pr state:merged`
      });

      const mergedPRs = prs.items.filter(pr => pr.pull_request?.merged_at);

      return {
        isContributor: mergedPRs.length > 0,
        prCount: mergedPRs.length,
        mergedPRs: mergedPRs.length
      };
    } catch (error) {
      console.error('GitHub API error:', error);
      return { isContributor: false, prCount: 0, mergedPRs: 0 };
    }
  }

  // 处理 PR 合并事件 → 自动奖励
  async handlePRMerged(prNumber: number, author: string): Promise<void> {
    const { prCount, mergedPRs } = await this.verifyContributor(author);

    // 关联 GitHub 账号到用户
    const user = await this.findUserByGitHub(author);
    if (!user) {
      // 如果用户还没注册，记录贡献，等注册时自动关联
      await this.recordUnclaimedContribution(author, prCount);
      return;
    }

    // 根据 PR 数量给予奖励
    if (prCount >= 10) {
      // 升级为 Ultimate（12个月免费）
      await this.subscriptionService.grantFreeTier(
        user.id, 
        'ultimate', 
        365,
        'community_contributor'
      );
      await this.notifyUser(user.id, '🎉 感谢你的贡献！你已获得 1 年 Ultimate 免费订阅');
    } else if (prCount >= 5) {
      // 升级为 Plus（6个月免费）
      await this.subscriptionService.grantFreeTier(
        user.id, 
        'plus', 
        180,
        'community_contributor'
      );
    } else if (prCount >= 2) {
      // 升级为 Pro（3个月免费）
      await this.subscriptionService.grantFreeTier(
        user.id, 
        'pro', 
        90,
        'community_contributor'
      );
    }
  }

  // 开发者的"好友位"功能
  async addDeveloperFriend(userId: string, friendUserId: string): Promise<void> {
    const user = await this.getUser(userId);
    if (user.tier !== 'ultimate') {
      throw new Error('Only Ultimate users can add developer friends');
    }

    // 好友获得 1 个月 Pro 试用
    await this.subscriptionService.grantFreeTier(
      friendUserId,
      'pro',
      30,
      'developer_friend'
    );

    // 记录好友关系
    await this.recordFriendRelation(userId, friendUserId);
  }
}
