### 增量识别算法

```typescript
// services/IncrementalDetector.ts
import { createHash } from 'crypto';

export class IncrementalDetector {
  /**
   * 生成用户信息指纹
   * 用于判断是否是同一个账号的不同导出
   */
  generateUserFingerprint(userData: any): string {
    // 从DeepSeek导出数据中提取用户特征
    const features = {
      // 使用多个特征组合生成唯一指纹
      email: userData.user?.email || '',
      userId: userData.user?.id || '',
      // 对话数量可作为辅助判断
      conversationCount: userData.conversations?.length || 0,
      // 创建时间范围
      earliestConversation: this.getEarliestDate(userData),
      latestConversation: this.getLatestDate(userData),
    };

    const fingerprintString = JSON.stringify(features);
    return createHash('sha256').update(fingerprintString).digest('hex');
  }

  /**
   * 判断是增量还是全新账号
   */
  async detectImportType(
    importData: any,
    existingUser: UserProfile | null
  ): Promise<{
    type: 'new_account' | 'incremental' | 'conflict';
    existingConversations?: StoredConversation[];
    newConversations?: StoredConversation[];
    duplicates?: string[];
  }> {
    const fingerprint = this.generateUserFingerprint(importData);

    if (!existingUser) {
      // 全新用户
      return { type: 'new_account' };
    }

    // 检查是否已有相同指纹的导入
    const existingImports = await this.getUserImports(existingUser.userId);
    const matchedImport = existingImports.find(
      imp => imp.userFingerprint === fingerprint
    );

    if (!matchedImport) {
      // 不同账号的导出
      return { type: 'new_account' };
    }

    // 相同账号，检查是否有新对话
    const newConversations = await this.findNewConversations(
      importData.conversations,
      matchedImport.conversationIds
    );

    if (newConversations.length === 0) {
      // 完全相同的数据
      return { type: 'conflict', duplicates: importData.conversations.map(c => c.id) };
    }

    // 有新增对话 → 增量导入
    return {
      type: 'incremental',
      existingConversations: await this.getConversations(matchedImport.conversationIds),
      newConversations: newConversations,
    };
  }

  /**
   * 合并增量数据
   */
  async mergeIncrementalData(
    userId: string,
    newData: any,
    existingFingerprint: string
  ): Promise<{
    added: number;
    updated: number;
    skipped: number;
  }> {
    // 检查每个对话是否已存在（通过ID或内容哈希）
    let added = 0, updated = 0, skipped = 0;

    for (const conv of newData.conversations) {
      const exists = await this.conversationExists(userId, conv.id);

      if (!exists) {
        // 新增对话
        await this.saveConversation(userId, conv, existingFingerprint);
        added++;
      } else {
        // 检查是否有更新（通过updated_at对比）
        const existing = await this.getConversation(userId, conv.id);
        if (new Date(conv.updated_at) > new Date(existing.updatedAt)) {
          await this.updateConversation(userId, conv);
          updated++;
        } else {
          skipped++;
        }
      }
    }

    return { added, updated, skipped };
  }
}
```

### API Key 安全存储

```typescript
// services/EncryptionService.ts
import crypto from 'crypto';

export class EncryptionService {
  private algorithm = 'aes-256-gcm';
  private key: Buffer;

  constructor(encryptionKey: string) {
    // 使用用户密码或主密钥派生
    this.key = crypto.scryptSync(encryptionKey, 'salt', 32);
  }

  /**
   * 加密 API Key
   */
  encrypt(text: string): { encrypted: string; iv: string; tag: string } {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(this.algorithm, this.key, iv);

    let encrypted = cipher.update(text, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const tag = cipher.getAuthTag().toString('hex');

    return { encrypted, iv: iv.toString('hex'), tag };
  }

  /**
   * 解密 API Key
   */
  decrypt(encrypted: string, iv: string, tag: string): string {
    const decipher = crypto.createDecipheriv(
      this.algorithm,
      this.key,
      Buffer.from(iv, 'hex')
    );
    decipher.setAuthTag(Buffer.from(tag, 'hex'));

    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  /**
   * 前端加密（用于传输前加密）
   */
  encryptForFrontend(text: string): string {
    // 使用Web Crypto API或简单的Base64编码
    // 实际传输使用HTTPS + 服务端加密
    return Buffer.from(text).toString('base64');
  }
}

