```typescript
// services/EnhancedSearch.ts
import FlexSearch from 'flexsearch';
import { db, SearchIndexRecord } from './db';

interface SearchOptions {
  query: string;
  limit?: number;
  fuzzy?: boolean;
  semantic?: boolean;  // Pro+ 语义搜索
  dateRange?: { start: string; end: string };
  tags?: string[];
}

export class EnhancedSearch {
  private index: FlexSearch.Index;
  private semanticSearch?: SemanticSearchService;  // Pro+

  constructor(private userTier: PlanTier) {
    this.index = new FlexSearch.Index({
      tokenize: this.getTokenizer(),
      cache: true,
      resolution: 9,
    });

    if (['pro', 'plus', 'ultimate'].includes(userTier)) {
      this.semanticSearch = new SemanticSearchService();
    }
  }

  private getTokenizer() {
    // 根据版本选择分词器
    return (text: string) => {
      // 基础分词
      let tokens = text.split(/[\s,，。！？；：""''（）\n\r\t]+/);

      // Pro+ 支持拼音搜索
      if (['pro', 'plus', 'ultimate'].includes(this.userTier)) {
        tokens = tokens.flatMap(t => [
          t,
          ...this.pinyinTokenize(t),  // 拼音分词
          ...this.fuzzyTokenize(t),   // 模糊匹配
        ]);
      }

      return tokens.filter(t => t.length > 0);
    };
  }

  async search(options: SearchOptions): Promise<SearchResult[]> {
    const { query, limit = 50, fuzzy = false, semantic = false } = options;

    // 获取用户配额
    const quota = this.getSearchQuota();
    if (this.userTier !== 'community' && this.userTier !== 'free') {
      // 检查配额
      await this.checkQuota();
    }

    let results: string[] = [];

    // 1. 关键词搜索（所有版本）
    results = await this.index.searchAsync(query, {
      limit: limit * 2,  // 多取一些用于去重和排序
      fuzzy: fuzzy && ['pro', 'plus', 'ultimate'].includes(this.userTier),
    });

    // 2. 语义搜索（Pro+）
    if (semantic && this.semanticSearch && 
        ['pro', 'plus', 'ultimate'].includes(this.userTier)) {
      const semanticResults = await this.semanticSearch.search(query, limit);
      // 合并去重
      results = [...new Set([...results, ...semanticResults])];
    }

    // 3. 获取完整数据
    const records = await this.getRecordsByIds(results);

    // 4. 按相关度排序
    return this.sortByRelevance(records, query);
  }

  private getSearchQuota(): number {
    switch (this.userTier) {
      case 'free': return 200;      // 200轮
      case 'pro': return 1000;      // 1000轮
      case 'plus':
      case 'ultimate': return Infinity;
      default: return Infinity;      // Community 无限制（本地）
    }
  }

  // 拼音分词（Pro+）
  private pinyinTokenize(text: string): string[] {
    // 使用 pinyin-pro 库
    return []; // 简化实现
  }

  // 模糊匹配（Pro+）
  private fuzzyTokenize(text: string): string[] {
    // 生成编辑距离 ≤ 2 的变体
