// services/AlpacaConverter.ts

export interface AlpacaSample {
  instruction: string;
  input?: string;
  output: string;
  system?: string;
  history?: { role: string; content: string }[];
}

export class AlpacaConverter {
  /**
   * 将DeepSeek对话转换为Alpaca格式
   */
  convert(conversation: StoredConversation): AlpacaSample[] {
    const samples: AlpacaSample[] = [];
    const messages = conversation.messages;

    // 提取系统提示（如果有）
    const systemPrompt = messages.find(m => m.role === 'system')?.content;

    // 提取所有 user-assistant 配对
    for (let i = 0; i < messages.length; i++) {
      if (messages[i].role === 'user') {
        const userMsg = messages[i];
        const assistantMsg = messages[i + 1];

        if (assistantMsg && assistantMsg.role === 'assistant') {
          // 检查是否有历史上下文
          const history = messages
            .slice(0, i)
            .filter(m => m.role !== 'system')
            .map(m => ({ role: m.role, content: m.content }));

          samples.push({
            instruction: userMsg.content,
            output: assistantMsg.content,
            system: systemPrompt,
            history: history.length > 0 ? history : undefined,
          });
        }
      }
    }

    return samples;
  }

  /**
   * 批量转换
   */
  convertAll(conversations: StoredConversation[]): AlpacaSample[] {
    const allSamples: AlpacaSample[] = [];
    for (const conv of conversations) {
      allSamples.push(...this.convert(conv));
    }
    return allSamples;
  }

  /**
   * 导出为 Alpaca JSON
   */
  exportToJSON(samples: AlpacaSample[]): string {
    return JSON.stringify(samples, null, 2);
  }

  /**
   * 导出为 Alpaca JSONL（用于训练）
   */
  exportToJSONL(samples: AlpacaSample[]): string {
    return samples.map(s => JSON.stringify(s)).join('\n');
  }
}

// 前端组件
// components/AlpacaExporter.tsx
export function AlpacaExporter() {
  const [format, setFormat] = useState<'json' | 'jsonl'>('json');
