// services/BalanceService.ts

export class BalanceService {
  /**
   * 查询 DeepSeek API 余额
   */
  async queryBalance(apiKey: string): Promise<{
    total: number;
    used: number;
    remaining: number;
    currency: string;
    expiresAt?: string;
  }> {
    try {
      // DeepSeek 官方 API 余额查询端点
      const response = await fetch('https://api.deepseek.com/v1/balance', {
        headers: {
          'Authorization': `Bearer ${apiKey}`,
        },
      });

      if (!response.ok) {
        throw new Error(`API error: ${response.status}`);
      }

      const data = await response.json();

      return {
        total: data.total_balance || 0,
        used: data.used_balance || 0,
        remaining: data.remaining_balance || 0,
        currency: data.currency || 'USD',
        expiresAt: data.expires_at,
      };
    } catch (error) {
      console.error('Balance query failed:', error);
      throw error;
    }
  }

  /**
   * 查询多个 Key 的余额（批量）
   */
  async queryMultipleBalances(apiKeys: string[]): Promise<{
    success: { key: string; balance: any }[];
    failed: { key: string; error: string }[];
  }> {
    const results = {
      success: [] as any[],
      failed: [] as any[],
    };

    await Promise.allSettled(
      apiKeys.map(async (key) => {
        try {
          const balance = await this.queryBalance(key);
          results.success.push({ key: this.maskKey(key), balance });
        } catch (error) {
          results.failed.push({ 
            key: this.maskKey(key), 
            error: error.message 
          });
        }
      })
    );

    return results;
  }

  private maskKey(key: string): string {
    return key.slice(0, 4) + '****' + key.slice(-4);
  }
}

