```typescript
// services/MigratableChat.ts

export interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface ChatConfig {
  model: string;
  temperature?: number;
  maxTokens?: number;
  topP?: number;
}

export class MigratableChat {
  private history: ChatMessage[] = [];
  private config: ChatConfig;
  private baseURL: string;
  private apiKey: string;

  constructor(config: {
    baseURL: string;
    apiKey: string;
    model?: string;
    temperature?: number;
  }) {
    this.baseURL = config.baseURL;
    this.apiKey = config.apiKey;
    this.config = {
      model: config.model || 'deepseek-chat',
      temperature: config.temperature || 0.7,
    };
  }

  /**
   * 从 DeepSeek 对话迁移上下文
   */
  importContext(conversation: StoredConversation): void {
    this.history = conversation.messages.map(msg => ({
      role: msg.role as 'user' | 'assistant' | 'system',
      content: msg.content,
    }));
  }

  /**
   * 发送消息（流式）
   */
  async *streamChat(
    message: string,
    onToken?: (token: string) => void
  ): AsyncGenerator<string> {
    // 添加用户消息到历史
    this.history.push({ role: 'user', content: message });

    const response = await fetch(`${this.baseURL}/v1/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.apiKey}`,
      },
      body: JSON.stringify({
        ...this.config,
        messages: this.history,
        stream: true,
      }),
    });

    if (!response.ok) {
      throw new Error(`API error: ${response.status}`);
    }

    const reader = response.body?.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    let fullResponse = '';

    while (reader) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (line.startsWith('data: ')) {
          const data = line.slice(6);
          if (data === '[DONE]') continue;

          try {
            const parsed = JSON.parse(data);
            const token = parsed.choices?.[0]?.delta?.content;
            if (token) {
              fullResponse += token;
              yield token;
              onToken?.(token);
            }
          } catch (e) {
            // 忽略解析错误
          }
        }
      }
    }

    // 保存助手响应到历史
    this.history.push({ role: 'assistant', content: fullResponse });
  }

  /**
   * 获取对话历史
   */
  getHistory(): ChatMessage[] {
    return this.history;
  }

  /**
   * 清空历史
   */
  clearHistory(): void {
    this.history = [];
  }

  /**
   * 导出为 DeepSeek 格式（回迁）
   */
  exportToDeepSeek(): StoredConversation {
    return {
      id: `migrated_${Date.now()}`,
      userId: 'migrated',
      title: '迁移对话',
      insertedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      userFingerprint: 'migrated',
      messages: this.history.map((msg, index) => ({
        id: `msg_${index}`,
        role: msg.role,
        content: msg.content,
        timestamp: new Date().toISOString(),
      })),
      metadata: {
        source: 'api',
        importDate: new Date().toISOString(),
        starred: false,
        isIncremental: false,
      },
    };
  }
}

