export function MigratableChatInterface() {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const [chatService, setChatService] = useState<MigratableChat | null>(null);
  const { apiKeys } = useStoredKeys();

  // 初始化或切换对话
  const initChat = (key: string, baseURL: string, conversation?: StoredConversation) => {
    const service = new MigratableChat({
      baseURL: baseURL || 'https://api.deepseek.com',
      apiKey: key,
    });

    if (conversation) {
      service.importContext(conversation);
    }

    setChatService(service);
    setMessages(service.getHistory());
  };

  const sendMessage = async () => {
    if (!chatService || !input.trim() || isStreaming) return;

    setIsStreaming(true);
    const userMessage = { role: 'user' as const, content: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');

    try {
      // 临时占位
      const assistantMessage = { role: 'assistant' as const, content: '' };
      setMessages(prev => [...prev, assistantMessage]);

      let fullContent = '';
      for await (const token of chatService.streamChat(input)) {
        fullContent += token;
        setMessages(prev => {
          const newMessages = [...prev];
          const last = newMessages[newMessages.length - 1];
          if (last.role === 'assistant') {
            last.content = fullContent;
          }
          return newMessages;
        });
      }
    } catch (error) {
      console.error('Stream error:', error);
    } finally {
      setIsStreaming(false);
    }
  };

  return (
    <div className="flex flex-col h-[600px] border rounded-lg">
      {/* 配置栏 */}
      <div className="p-3 border-b bg-gray-50 flex gap-2">
        <select className="flex-1 p-1 border rounded text-sm">
