### 增量检测逻辑

```typescript
// services/ImportService.ts
import crypto from 'crypto';
import { v4 as uuidv4 } from 'uuid';

export class ImportService {
  /**
   * 检测导入数据是增量还是全新账号
   */
  async detectImportType(userId: string, rawData: any): Promise<{
    type: 'new' | 'incremental' | 'conflict';
    existingUserInfo?: any;
    newConversations: any[];
    updatedConversations: any[];
  }> {
    // 1. 提取用户信息
    const userInfo = this.extractUserInfo(rawData);
    const userInfoHash = crypto
      .createHash('sha256')
      .update(JSON.stringify(userInfo))
      .digest('hex');

    // 2. 查询该用户的导入历史
    const lastImport = await db.importBatches
      .where('user_id')
      .equals(userId)
      .sortBy('imported_at', 'desc')
      .first();

    if (!lastImport) {
      // 首次导入 → 全新账号
      return {
        type: 'new',
        newConversations: rawData.conversations,
        updatedConversations: []
      };
    }

    // 3. 对比用户信息Hash
    const lastUserInfoHash = crypto
      .createHash('sha256')
      .update(JSON.stringify(lastImport.user_info))
      .digest('hex');

    if (userInfoHash === lastUserInfoHash) {
      // 同一用户 → 增量更新
      const { newConvs, updatedConvs } = await this.detectIncremental(
        userId,
        rawData.conversations
      );
      return {
        type: 'incremental',
        existingUserInfo: lastImport.user_info,
        newConversations: newConvs,
        updatedConversations: updatedConvs
      };
    } else {
      // 用户信息不同 → 可能是切换账号
      return {
        type: 'conflict',
        existingUserInfo: lastImport.user_info,
        newConversations: rawData.conversations,
        updatedConversations: []
      };
    }
  }

  /**
   * 检测增量对话
   */
  private async detectIncremental(
    userId: string,
    newConversations: any[]
  ): Promise<{
    newConvs: any[];
    updatedConvs: any[];
  }> {
    const newConvs: any[] = [];
    const updatedConvs: any[] = [];

    // 获取用户现有对话ID集合
    const existingIds = new Set(
      (await db.conversationsMeta
        .where('user_id')
        .equals(userId)
        .toArray())
        .map(c => c.original_conversation_id)
    );

    for (const conv of newConversations) {
      if (existingIds.has(conv.id)) {
        // 对话已存在 → 检查是否需要更新
        const existing = await db.conversationsMeta
          .where({
            user_id: userId,
            original_conversation_id: conv.id
          })
          .first();

        // 比较消息数量或最后更新时间
        if (conv.messages.length > existing?.message_count) {
          updatedConvs.push(conv);
        }
      } else {
        newConvs.push(conv);
      }
    }

    return { newConvs, updatedConvs };
  }

  /**
   * 执行导入
   */
  async importConversations(
    userId: string,
    rawData: any,
    type: 'new' | 'incremental'
  ): Promise<{
    importedCount: number;
    updatedCount: number;
    totalMessages: number;
  }> {
    const importId = uuidv4();
    let importedCount = 0;
    let updatedCount = 0;
    let totalMessages = 0;

    const conversations = rawData.conversations;

    for (const conv of conversations) {
      const existing = await db.conversationsMeta
        .where({
          user_id: userId,
          original_conversation_id: conv.id
        })
        .first();

      if (existing && type === 'incremental') {
        // 更新现有对话
        await this.updateConversation(existing.id, conv);
        updatedCount++;
      } else {
        // 创建新对话
        await this.createConversation(userId, importId, conv);
        importedCount++;
      }

      totalMessages += conv.messages.length;
    }

    // 记录导入批次
    await db.importBatches.add({
      id: uuidv4(),
      user_id: userId,
      import_id: importId,
      user_info: this.extractUserInfo(rawData),
      conversation_count: conversations.length,
      message_count: totalMessages,
      file_size: Buffer.byteLength(JSON.stringify(rawData)),
      imported_at: new Date(),
      status: 'completed'
    });

    // 更新用户配额
    await this.updateUserQuota(userId, totalMessages);

    return { importedCount, updatedCount, totalMessages };
  }
}
```

### API Key 加密存储

```typescript
// services/EncryptionService.ts
import crypto from 'crypto';

export class EncryptionService {
  private algorithm = 'aes-256-gcm';
  private key: Buffer;

  constructor() {
    // 从环境变量获取主密钥
    const masterKey = process.env.MASTER_ENCRYPTION_KEY!;
    this.key = crypto.scryptSync(masterKey, 'salt', 32);
  }

  encrypt(text: string): { encrypted: string; iv: string; tag: string } {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(this.algorithm, this.key, iv);

    let encrypted = cipher.update(text, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const tag = cipher.getAuthTag().toString('hex');

    return { encrypted, iv: iv.toString('hex'), tag };

你提到的这个需求，本质上就是搭建一个**URL代理服务**——它像一座桥，让AI抓取器通过你的VPS去访问目标网页，从而绕过那些对AI不友好的封禁或访问限制。

下面给你一套完整的实战方案，用你提到的 `fastlink.com/<url>` 这个格式来理解，就是 `你的域名/<目标网址>`。

### 核心原理
AI访问目标网站时返回404，通常是因为网站检测到了AI的`User-Agent`或IP。你的VPS方案就是“中间人”：VPS请求目标网站（伪装成普通浏览器），拿到内容后再返回给AI。

---

### 方案一：轻量级PHP代理（最快部署）
适合快速验证，用PHP几行代码就能搞定。

1. **在VPS新建文件**，比如 `/var/www/html/index.php`
2. **写入代码**：
```php
<?php
// 获取URL参数，例如访问 https://你的域名/?url=https://example.com
$targetUrl = $_GET['url'] ?? '';

if (empty($targetUrl)) {
    die('请提供url参数');
}

// 初始化cURL，模拟真实浏览器
$ch = curl_init();
curl_setopt($ch, CURLOPT_URL, $targetUrl);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');
curl_setopt($ch, CURLOPT_TIMEOUT, 30);

$response = curl_exec($ch);
$httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
curl_close($ch);

// 原样返回内容
http_response_code($httpCode);
header('Content-Type: text/html; charset=utf-8');
echo $response;
?>
```

3. **访问方式**：`https://你的域名/?url=https://目标网站.com/xxx`  
如果想改成你提到的 `fastlink.com/<url>` 格式（路径参数），需要配合Nginx重写规则，后面会讲。

---

### 方案二：高性能Nginx + Lua（生产级）
如果你的VPS访问量较大，用Nginx的`ngx_http_proxy_module`配合Lua脚本效率更高。

1. **安装OpenResty**（集成Lua的Nginx）或编译添加Lua模块。
2. **配置Nginx**，支持路径参数转发：
```nginx
server {
    listen 80;
    server_name 你的域名.com;

    # 将 /https://example.com 这种格式解析为目标URL
    location ~ ^/(https?://.+) {
        # 捕获目标URL
        set $target_url $1;

        # 代理请求
        proxy_pass $target_url;
        proxy_set_header User-Agent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36";
        proxy_set_header Referer "";
        proxy_set_header Accept-Encoding "";
        proxy_ssl_server_name on;
        proxy_ssl_protocols TLSv1.2 TLSv1.3;

        # 处理重定向
        proxy_redirect off;
        proxy_set_header Host $proxy_host;
    }
}
```
这样你就可以直接用 `https://你的域名/https://目标网站.com` 来访问了。

