### 方案二：Nginx版本（更高效，推荐）

使用Nginx的**sub_filter**模块，在代理响应时直接过滤：

```nginx
server {
    listen 443 ssl http2;
    server_name 你的域名.com;

    ssl_certificate /etc/letsencrypt/live/你的域名.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/你的域名.com/privkey.pem;

    # 只处理静态内容路径
    location ~ ^/(https?://.+)$ {
        set $target_url $1;

        # 只允许GET请求
        if ($request_method != GET) {
            return 405;
        }

        # 代理设置
        proxy_pass $target_url;
        proxy_set_header User-Agent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36";
        proxy_set_header Accept "text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8";
        proxy_set_header Accept-Encoding "gzip, deflate, br";
        proxy_set_header Connection "keep-alive";

        # 关键：限制响应大小（防止加载大文件）
        proxy_max_temp_file_size 0;
        proxy_buffer_size 128k;
        proxy_buffers 4 256k;
        proxy_busy_buffers_size 256k;

        # 只缓存HTML、CSS、图片等静态资源
        proxy_cache_valid 200 302 1h;
        proxy_cache_valid 404 1m;
        proxy_cache_key "$scheme$proxy_host$request_uri";

        # 内容过滤：移除JS
        sub_filter '</head>' '<style>/* 静态内容 */</style></head>';
        sub_filter_once off;
        sub_filter_types text/html;

        # 更激进的做法：用正则替换（需安装ngx_http_substitutions_filter_module）
        # 这里用多个sub_filter移除常见动态内容
        sub_filter '<script' '<!-- removed-script';
        sub_filter '</script>' '-->';
        sub_filter 'onclick=' 'data-removed=';
        sub_filter 'onload=' 'data-removed=';
        sub_filter 'onerror=' 'data-removed=';

        # 禁用压缩，确保sub_filter能正常工作
        proxy_set_header Accept-Encoding "";

        # 超时设置
        proxy_connect_timeout 10s;
        proxy_read_timeout 30s;
    }

    # 禁止访问其他路径
    location / {
        return 403;
    }
}
```

