## 方案一：Tesseract OCR（免费开源，推荐）

### 1. 安装Tesseract

```bash
# Ubuntu/Debian
sudo apt update
sudo apt install tesseract-ocr tesseract-ocr-eng tesseract-ocr-chi-sim  # 中文简体和英文
sudo apt install libtesseract-dev

# CentOS/RHEL
sudo yum install epel-release
sudo yum install tesseract tesseract-devel tesseract-langpack-eng tesseract-langpack-chi-sim
```

### 2. 安装PHP扩展（可选）

```bash
# 使用composer安装tesseract的PHP包装器
composer require thiagoalessio/tesseract_ocr
```

### 3. 完整的PHP代码实现

```php
<?php
require_once 'vendor/autoload.php';

use thiagoalessio\TesseractOCR\TesseractOCR;

$targetUrl = $_GET['url'] ?? '';

if (empty($targetUrl)) {
    die(json_encode(['error' => '请提供url参数']));
}

// 1. 抓取目标页面
$ch = curl_init();
curl_setopt($ch, CURLOPT_URL, $targetUrl);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36');
curl_setopt($ch, CURLOPT_TIMEOUT, 30);
$html = curl_exec($ch);
curl_close($ch);

// 2. 提取所有图片URL
$imageUrls = extractImageUrls($html, $targetUrl);

// 3. OCR识别每张图片
$ocrResults = [];
foreach ($imageUrls as $imgUrl) {
    $text = recognizeImage($imgUrl);
    if ($text) {
        $ocrResults[] = [
            'url' => $imgUrl,
            'text' => $text
        ];
    }
}

// 4. 合并结果
$result = [
    'url' => $targetUrl,
    'html' => filterStaticContent($html),
    'images' => $ocrResults,
    'total_text' => implode("\n\n", array_column($ocrResults, 'text'))
];

// 5. 返回JSON（方便AI解析）
header('Content-Type: application/json; charset=utf-8');
echo json_encode($result, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

/**
 * 提取HTML中的所有图片URL
 */
function extractImageUrls($html, $baseUrl) {
    $urls = [];
    $dom = new DOMDocument();
    @$dom->loadHTML($html);
    $images = $dom->getElementsByTagName('img');

    foreach ($images as $img) {
        $src = $img->getAttribute('src');
        if ($src) {
            // 转换为绝对URL
            $fullUrl = absoluteUrl($src, $baseUrl);
            if ($fullUrl) {
                $urls[] = $fullUrl;
            }
        }
    }
    return array_slice($urls, 0, 10); // 限制最多识别10张图，防止超时
}

/**
 * 将相对URL转为绝对URL
 */
function absoluteUrl($relative, $base) {
    if (parse_url($relative, PHP_URL_SCHEME) != '') {
        return $relative;
    }
    if ($relative[0] == '/') {
        $parts = parse_url($base);
        return $parts['scheme'] . '://' . $parts['host'] . $relative;
    }
    return rtrim($base, '/') . '/' . ltrim($relative, '/');
}

/**
 * OCR识别单张图片
 */
function recognizeImage($imageUrl) {
    // 下载图片到临时文件
    $tmpFile = tempnam(sys_get_temp_dir(), 'ocr_');
    $ch = curl_init($imageUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
    curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36');
    curl_setopt($ch, CURLOPT_TIMEOUT, 10);
    $imageData = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($httpCode !== 200 || !$imageData) {
        return null;
    }

    file_put_contents($tmpFile, $imageData);

    // 检查图片格式，如果不是标准格式，尝试转换
    $mime = mime_content_type($tmpFile);
    if (!in_array($mime, ['image/jpeg', 'image/png', 'image/gif', 'image/bmp', 'image/webp'])) {
        unlink($tmpFile);
        return null;
    }

    try {
        // 使用Tesseract识别
        $ocr = new TesseractOCR($tmpFile);
        $ocr->lang('eng+chi_sim');  // 中英文混合识别
        $ocr->psm(6);  // 页面分割模式：6 = 统一文本块
        $text = $ocr->run();

        // 清理识别结果
        $text = trim(preg_replace('/\s+/', ' ', $text));

        unlink($tmpFile);
        return $text ?: null;
    } catch (Exception $e) {
        unlink($tmpFile);
        error_log("OCR Error: " . $e->getMessage());
        return null;
    }
}

/**
 * 过滤静态内容（复用之前的函数）
 */
function filterStaticContent($html) {
    $html = preg_replace('/<script[^>]*>.*?<\/script>/is', '', $html);
    $html = preg_replace('/\s+on\w+="[^"]*"/i', '', $html);
    $html = preg_replace("/\s+on\w+='[^']*'/i", '', $html);
    $html = preg_replace('/<iframe[^>]*>.*?<\/iframe>/is', '', $html);
    $html = preg_replace('/<form[^>]*>.*?<\/form>/is', '', $html);
    return $html;
}
?>
